class Config { int timeout = 10; }
public static void update(Config c) {
    c.timeout = 20;
    c = new Config();
    c.timeout = 30;
}
public static void main(String[] args) {
    Config cfg = new Config();
    update(cfg);
    System.out.println(cfg.timeout);
}
